import asyncio
from datetime import timedelta
from decimal import Decimal
from typing import Literal

from pydantic import TypeAdapter, ValidationError, model_serializer

from ..core import models as m
from ..core.diagnostics import AdmissionDiagnostic
from ..core.errors import ContractViolation
from ..core.serialization import semantic_hash


class ModelCallTrace(m.FrozenModel):
    request: m.ModelRequest
    request_hash: str
    result_kind: Literal[
        "success", "refused", "invalid", "timeout", "capacity_unavailable", "transport_failure", "cancelled",
    ]
    usage: m.ModelUsage
    charged_tokens: int
    elapsed_s: Decimal
    response_hash: str | None = None
    permitted_raw_response: str | None = None
    cause: str | None = None
    consumer_admitted: bool | None = None
    fallback_used: bool = False
    fallback_reason: str | None = None
    diagnostic: AdmissionDiagnostic | None = None

    @model_serializer(mode="wrap")
    def preserve_historic_projection(self, handler):
        result = handler(self)
        additions = {"consumer_admitted", "fallback_used", "fallback_reason", "diagnostic"}
        # Old persisted traces have a hash over the old projection. Preserve those bytes'
        # semantic projection on export; absence means unknown admission, never success.
        if not additions & self.model_fields_set:
            for key in additions:
                result.pop(key, None)
        return result


def failure(request, kind, detail, elapsed=Decimal("0")):
    cls, code = {
        "invalid": (m.ModelInvalid, "model_invalid"),
        "refused": (m.ModelRefused, "model_invalid"),
        "timeout": (m.ModelTimeout, "model_timeout"),
        "capacity_unavailable": (m.ModelCapacityUnavailable, "unsupported_capability"),
        "transport_failure": (m.ModelTransportFailure, "recovery_required"),
    }[kind]
    return cls(kind=kind, call_id=request.call_id, model_id=request.model_id, elapsed_s=elapsed,
               issues=(m.Issue(code=code, severity="error", component="model", refs=(), detail=detail),))


class DecisionModelLedger:
    # Historical reviewed caps, now owned in one place and clipped by the live
    # decision remainder. A later measured policy can replace these values once.
    stage_caps_s = {"interpret": 8.0, "propose": 4.0, "select": 4.0}

    def __init__(self, *, budget: m.DecisionBudget, clock, token_limit: int):
        if type(token_limit) is not int or token_limit <= 0:
            raise ValueError("explicit positive decision token limit required")
        self.budget = m.DecisionBudget.model_validate_json(budget.model_dump_json())
        self.clock = clock
        self.token_limit = token_limit
        self.started = clock.monotonic()
        self.calls = 0
        self.tokens = 0
        self.model_seconds = 0.0
        self.traces: list[ModelCallTrace] = []
        self.seen = set()
        self.busy = False
        self.disabled_reason: str | None = None

    def remaining(self):
        reserves = float(self.budget.fallback_reserve_s + self.budget.submission_reserve_s)
        return min(
            (self.budget.deadline_at - self.clock.utcnow()).total_seconds() - reserves,
            float(self.budget.compute_limit_s) - (self.clock.monotonic() - self.started) - reserves,
            float(self.budget.model_time_limit_s) - self.model_seconds,
        )

    def model_budget(self, *, task, max_tokens, time_limit_s):
        remaining = min(self.remaining(), float(time_limit_s), self.stage_caps_s.get(task, float(time_limit_s)))
        if remaining <= 0:
            raise ContractViolation("model_timeout: no model time remains after reserves")
        return m.ModelBudget(deadline_at=self.clock.utcnow() + timedelta(seconds=remaining),
                             time_limit_s=Decimal(str(remaining)), max_tokens=max_tokens, max_calls=1, retry_limit=0)

    def disable(self, reason, transport=None):
        if self.disabled_reason is None:
            self.disabled_reason = reason
        stopper = getattr(transport, "stop_model_calls", None)
        if callable(stopper):
            stopper(reason)

    async def invoke(self, request, budget, transport):
        request = m.ModelRequest.model_validate_json(request.model_dump_json())
        budget = m.ModelBudget.model_validate_json(budget.model_dump_json())
        timeout = min(self.remaining(), float(budget.time_limit_s),
                      (budget.deadline_at - self.clock.utcnow()).total_seconds())
        if getattr(transport, "stopped", False) and self.disabled_reason is None:
            self.disabled_reason = "transport_unavailable"
        if (self.disabled_reason is not None or self.busy or request.call_id in self.seen
                or self.calls >= self.budget.model_call_limit
                or self.tokens + budget.max_tokens > self.token_limit):
            reason = self.disabled_reason or "decision call/token capacity exhausted"
            result = failure(request, "capacity_unavailable", reason)
            self._record(request, result, 0, 0.0)
            return result
        if timeout <= 0:
            result = failure(request, "timeout", "decision reserves/deadline exhausted")
            self._record(request, result, 0, 0.0)
            return result
        # Reserve before any await, including queue time; never retry a call identity.
        self.busy = True
        self.seen.add(request.call_id)
        self.calls += 1
        self.tokens += budget.max_tokens
        started = self.clock.monotonic()
        loop_started = asyncio.get_running_loop().time()
        cancelled = False
        try:
            # Do not wait indefinitely for a cancellation-resistant child.
            # A detached late child is observed and never admitted.
            task = asyncio.create_task(transport(request, budget))
            done, _ = await asyncio.wait({task}, timeout=timeout)
            if not done:
                task.cancel()
                task.add_done_callback(_consume)
                self.disable("model_timeout", transport)
                result = failure(request, "timeout", "transport exceeded model deadline")
            else:
                result = TypeAdapter(m.ModelResult).validate_json(task.result().model_dump_json())
                elapsed = max(self.clock.monotonic() - started, asyncio.get_running_loop().time() - loop_started)
                if (elapsed >= timeout or float(result.elapsed_s) >= timeout
                        or self.remaining() <= 0 or self.clock.utcnow() >= budget.deadline_at):
                    result = failure(request, "timeout", "late model result rejected")
                elif result.call_id != request.call_id or result.model_id != request.model_id:
                    result = failure(request, "invalid", "call/model identity mismatch")
                elif result.kind == "success" and any(i.severity == "error" for i in result.issues):
                    result = failure(request, "invalid", "successful transport contains error issues")
                if result.kind in {"timeout", "transport_failure"}:
                    self.disable(result.kind, transport)
        except asyncio.CancelledError:
            cancelled = True
            # Revoke admission synchronously. The caller may fall back, but no stage in
            # this decision can reserve another request while cleanup is still running.
            self.disable("caller_cancelled", transport)
            task.cancel()
            task.add_done_callback(_consume)
            raise
        except (ValidationError, ValueError, TypeError, AttributeError):
            result = failure(request, "invalid", "malformed transport envelope")
        except TimeoutError:
            result = failure(request, "timeout", "transport timeout")
            self.disable("model_timeout", transport)
        except Exception:
            result = failure(request, "transport_failure", "transport failed; details withheld")
            self.disable("transport_failure", transport)
        finally:
            elapsed = max(0.0, self.clock.monotonic() - started,
                          asyncio.get_running_loop().time() - loop_started)
            self.model_seconds += elapsed
            self.busy = False
            if cancelled:
                self.traces.append(ModelCallTrace(
                    request=request, request_hash=semantic_hash(request), result_kind="cancelled", usage=m.ModelUsage(),
                    charged_tokens=budget.max_tokens, elapsed_s=Decimal(str(elapsed)), cause="cancelled",
                ))
        charged = budget.max_tokens
        if result.kind == "success":
            usage = result.usage
            if usage.input_tokens is not None and usage.output_tokens is not None:
                actual = usage.input_tokens + usage.output_tokens
                if actual <= budget.max_tokens:
                    charged = actual
                    self.tokens -= budget.max_tokens - actual
                else:
                    # Report overrun truthfully and block subsequent admissions.
                    self.tokens += actual - budget.max_tokens
                    charged = actual
                    self._record(request, result, charged, elapsed)
                    return failure(request, "invalid", "reported usage exceeds reservation")
        self._record(request, result, charged, elapsed)
        return result

    def _record(self, request, result, charged, elapsed):
        self.traces.append(ModelCallTrace(
            request=request, request_hash=semantic_hash(request), result_kind=result.kind,
            usage=result.usage if result.kind == "success" else m.ModelUsage(), charged_tokens=charged,
            elapsed_s=Decimal(str(elapsed)), response_hash=result.response_hash if result.kind == "success" else None,
            cause=result.issues[0].code if result.issues else None,
            diagnostic=(AdmissionDiagnostic(stage="execution", category="execution_failure", error_type="execution")
                        if result.kind != "success" else None),
        ))

    def reject_raw(self, call_id, code, diagnostic=None):
        for index, trace in enumerate(self.traces):
            if trace.request.call_id == call_id:
                self.traces[index] = trace.model_copy(update={"cause": code, "permitted_raw_response": None,
                    "consumer_admitted": False, "fallback_used": True, "fallback_reason": code,
                    "diagnostic": diagnostic or AdmissionDiagnostic(stage="consumer", category="unattributable",
                                                                    error_type="unknown")})
                return

    def admit_raw(self, call_id, raw):
        for index, trace in enumerate(self.traces):
            if trace.request.call_id == call_id and trace.result_kind == "success":
                self.traces[index] = trace.model_copy(update={"permitted_raw_response": raw, "consumer_admitted": True})
                return


def _consume(task):
    if not task.cancelled():
        task.exception()
            raise ValueError("explicit credentials and nonredirecting async client required")
        self._api_key, self.client = api_key, client

    async def __call__(self, request: m.ModelRequest, budget: m.ModelBudget) -> m.ModelResult:
        started = time.monotonic()

        def elapsed():
            return Decimal(str(max(0, time.monotonic() - started)))

        try:
            messages = messages_for(request, self.config)
            output_format = response_format(request, self.config)
            bound = input_token_upper_bound(messages, self.config.framing_token_reserve,
                                            output_format if self.config.structured_output else None)
            output_limit = min(self.config.max_output_tokens, budget.max_tokens - bound)
            if output_limit <= 0:
                return failure(request, "capacity_unavailable", "input leaves no output token allowance", elapsed())
            body = {
                "model": self.config.request_model_id or self.config.model_id,
                "messages": messages,
                self.config.token_parameter: output_limit,
                "response_format": output_format,
                "stream": False,
            }
            # Stream the HTTP bytes only to bound envelope size; no model streaming/retries.
            async with self.client.stream(
                "POST",
                self.config.base_url.rstrip("/") + "/chat/completions",
                headers={"Authorization": "Bearer " + self._api_key},
                json=body,
                timeout=float(budget.time_limit_s),
                follow_redirects=False,
            ) as response:
                if response.status_code == 429:
                    return failure(request, "capacity_unavailable", "provider capacity unavailable", elapsed())
                if response.status_code != 200:
                    return failure(
                        request, "transport_failure", "provider HTTP request rejected; body withheld", elapsed()
                    )
                raw = bytearray()
                async for chunk in response.aiter_bytes():
                    raw.extend(chunk)
                    if len(raw) > self.config.max_response_bytes:
                        return failure(request, "invalid", "oversized provider envelope", elapsed())
            data = json.loads(raw)
            choices = data["choices"]
            if len(choices) != 1:
                return failure(request, "invalid", "one provider choice required", elapsed())
            choice = choices[0]
            message = choice["message"]
            if message.get("refusal") or choice.get("finish_reason") == "content_filter":
                return failure(request, "refused", "provider refused; content withheld", elapsed())
            if choice.get("finish_reason") != "stop" or message.get("tool_calls") or message.get("function_call"):
                return failure(request, "invalid", "incomplete or nontext provider output", elapsed())
            content = message["content"]
            if not isinstance(content, str):
                return failure(request, "invalid", "provider content must be text", elapsed())
            usage = data.get("usage") or {}
            result = m.ModelSuccess(
                kind="success",
                call_id=request.call_id,
                model_id=data["model"],
                elapsed_s=elapsed(),
                issues=(),
                raw_response_json=content,
                response_hash=hashlib.sha256(content.encode()).hexdigest(),
                usage=m.ModelUsage(
                    input_tokens=usage.get("prompt_tokens"), output_tokens=usage.get("completion_tokens")
                ),
            )
            if (
                result.model_id != request.model_id
                or result.usage.input_tokens is not None
                and result.usage.input_tokens > bound
                or result.usage.output_tokens is not None
                and result.usage.output_tokens > output_limit
            ):
                # Ledger retains actual successful usage and rejects total-reservation overruns.
                # A within-total provider violation is an invalid successful envelope, so
                # conservative unknown/full-reservation accounting remains in force.
                if (result.usage.input_tokens or 0) + (result.usage.output_tokens or 0) > budget.max_tokens:
                    return result
                return failure(request, "invalid", "provider identity/token-bound violation", elapsed())
            return result
        except httpx.TimeoutException:
            return failure(request, "timeout", "provider HTTP timeout", elapsed())
        except httpx.HTTPError:
            return failure(request, "transport_failure", "provider transport failed; details withheld", elapsed())
        except (ValueError, KeyError, TypeError, AttributeError):
            return failure(request, "invalid", "malformed provider envelope/configuration", elapsed())
        return (await self.run_once(snapshot)).outcome

    async def run_once(
        self,
        snapshot: m.DecisionSnapshot,
        *,
        previous_assessment: m.SupplierAssessment | None = None,
        recorded_input_bytes: bytes = b"",
    ) -> OfflineDecisionTrace:
        consumer = next((c for c in (self.interpreter, self.proposal, self.selector)
                         if hasattr(c, "decision_scope")), None)
        if consumer is None:
            return await self._run_once(snapshot, previous_assessment=previous_assessment,
                                        recorded_input_bytes=recorded_input_bytes)
        if self.model_token_limit is None:
            raise ContractViolation("unsupported_capability: explicit total model token budget required")
        ledger = DecisionModelLedger(budget=snapshot.budget, clock=self.clock, token_limit=self.model_token_limit)
        with consumer.decision_scope(ledger):
            trace = await self._run_once(snapshot, previous_assessment=previous_assessment,
                                         recorded_input_bytes=recorded_input_bytes)
        trace = trace.model_copy(update={"model_calls": tuple(ledger.traces),
                                        "model_token_limit": ledger.token_limit})
        trace = trace.model_copy(update={"trace_hash": semantic_hash(
            trace.model_dump(mode="json", exclude={"trace_hash"}),
        )})
        trace.verify()
        return trace

    async def _run_once(
        self,
        snapshot: m.DecisionSnapshot,
        *,
        previous_assessment: m.SupplierAssessment | None = None,
        recorded_input_bytes: bytes = b"",
    ) -> OfflineDecisionTrace:
        raw_snapshot = canonical_json(snapshot)
        ref = snapshot.context.snapshot
        stages = []
        issues = []
        generations = []
        assessment = intents = batch = decision = rendered = validation = payload = None
        phase = "snapshot"
        started = self.clock.monotonic()
        phase_started = started

        def remaining():
            utc = (snapshot.budget.deadline_at - self.clock.utcnow()).total_seconds()
            compute = float(snapshot.budget.compute_limit_s) - (self.clock.monotonic() - started)
            return min(utc, compute)

        def available():
            if remaining() <= 0:
                raise ContractViolation("deadline_exhausted: offline decision budget exhausted")

        async def bounded(call: Callable[[], Awaitable[T]]) -> T:
            available()
            return await asyncio.wait_for(call(), timeout=remaining())

        def completed():
            nonlocal phase_started
            stage_issues = ()
            if phase == "interpretation" and assessment is not None and assessment.status == "fallback":
                codes = [code for code in assessment.unknowns if code in m.IssueCode.__args__]
                stage_issues = tuple(m.Issue(code=code, severity="warning", component="interpretation",
                                            refs=(), detail="consumer rejected interpretation; fallback used")
                                     for code in codes)
                issues.extend(stage_issues)
            stages.append(OfflineStage(name=phase, status="completed", issues=stage_issues,
                                       elapsed_s=Decimal(str(max(0, self.clock.monotonic() - phase_started)))))
            phase_started = self.clock.monotonic()

        def begin(name):
            nonlocal phase, phase_started
            phase = name
            phase_started = self.clock.monotonic()

        try:
            snapshot = m.DecisionSnapshot.model_validate_json(raw_snapshot)
            if snapshot.state.version != ref.state_version:
                raise ContractViolation("stale_state: decision state version differs from snapshot")
            context = snapshot.context
            if (
                case_contract_hash(context.case) != ref.case_contract_hash
                or context.evidence.as_of != context.as_of
                or context.as_of > self.clock.utcnow()
                or "sha256:" + semantic_hash(context.evidence.model_dump(mode="json", exclude={"context_version"}))
                != ref.context_version
                or economic_fingerprint(context.economic) != context.economic.fingerprint
            ):
                raise ContractViolation("stale_state: stale or edited context projection")
            if any(i.severity == "error" for i in (*context.evidence.gaps, *context.economic.issues)) or any(
                c.blocking for c in context.evidence.conflicts
            ):
                raise ContractViolation("source_conflict: snapshot has unresolved evidence/economic errors")
            if snapshot.state.runtime_status not in ("ready", "deciding") or any(
                o.status in ("prepared", "submitted", "uncertain") for o in snapshot.state.operations
            ):
                raise ContractViolation("operation_pending: decision has unresolved ownership")
            if previous_assessment is not None and (
                previous_assessment.supplier_id != snapshot.target_supplier_id
                or previous_assessment.snapshot.run_id != ref.run_id
                or previous_assessment.snapshot.session_id != ref.session_id
                or previous_assessment.snapshot.state_version > ref.state_version
            ):
                raise ContractViolation("stale_state: previous assessment belongs to another/future state")
            available()
            completed()
            begin("interpretation")
            assessment = await bounded(
                lambda: self.interpreter.interpret(
                    context,
                    snapshot.conversation,
                    previous_assessment,
                    snapshot.budget,
                )
            )
            assessment = m.SupplierAssessment.model_validate_json(assessment.model_dump_json())
            _assessment(assessment, snapshot)
            completed()
            begin("proposal")
            intents = await bounded(
                lambda: self.proposal.propose_strategies(
                    context,
                    assessment,
                    snapshot.state,
                    snapshot.budget,
                    self.research,
                )
            )
            intents = m.IntentBatch.model_validate_json(intents.model_dump_json())
            issues.extend(intents.issues)
            if intents.snapshot != ref or not intents.intents or len(intents.intents) > snapshot.budget.candidate_limit:
                raise ContractViolation("invalid_schema: proposal returned empty/oversized/stale intent batch")
            for intent in intents.intents:
                if intent.supplier_id != snapshot.target_supplier_id:
                    raise ContractViolation("scope_mismatch: proposed intent targets another supplier")
                if not set(intent.observation_refs) <= {o.observation_id for o in assessment.observations}:
                    raise ContractViolation("ungrounded_output: intent references unknown observation")
                for citation in (*intent.evidence_refs, *intent.proposal_citations):
                    _citation(citation, snapshot)
            if any(i.severity == "error" for i in intents.issues):
                raise ContractViolation("infeasible: proposal contains unresolved errors")
            completed()
            begin("generation")
            for intent in intents.intents:
                available()
                generated = self.generator.generate_candidates(intent, context, snapshot.state, snapshot.budget)
                generated = m.GenerationResult.model_validate_json(generated.model_dump_json())
                generations.append(generated)
                issues.extend(generated.rejections)
                if generated.intent_id != intent.intent_id or any(
                    c.intent_id != intent.intent_id
                    or c.supplier_id != snapshot.target_supplier_id
                    or c.snapshot != ref
                    or c.candidate_id != candidate_id(c)
                    for c in generated.candidates
                ):
                    raise ContractViolation("invalid_schema: generator returned forged candidate/snapshot")
            candidates = tuple(c for g in generations for c in g.candidates)
            if not candidates or len(candidates) > min(20, snapshot.budget.candidate_limit):
                raise ContractViolation("infeasible: no candidates or global candidate budget exceeded")
            completed()
            begin("evaluation")
            available()
            batch = self.evaluator.evaluate_candidates(candidates, context)
            batch = m.EvaluationBatch.model_validate_json(batch.model_dump_json())
            verify_batch(batch)
            if batch.snapshot != ref or {i.candidate.candidate_id: i.candidate for i in batch.items} != {
                c.candidate_id: c for c in candidates
            }:
                raise ContractViolation("invalid_schema: evaluator changed registered candidate membership")
            issues.extend(i for item in batch.items for i in item.issues)
            completed()
            begin("selection")
            decision = await bounded(
                lambda: self.selector.select_action(
                    batch,
                    assessment,
                    snapshot.state,
                    snapshot.budget,
                    self.research,
                )
            )
            decision = m.NegotiationDecision.model_validate_json(decision.model_dump_json())
            selected = next((i for i in batch.items if i.candidate.candidate_id == decision.candidate_id), None)
            if (
                selected is None
                or selected.disposition != "approved"
                or decision.snapshot != ref
                or decision.approved_batch_hash != batch.batch_hash
                or decision.evaluation_id != selected.evaluation_id
            ):
                raise ContractViolation("invalid_schema: selection is not an approved registered batch member")
            for citation in decision.citations:
                _citation(citation, snapshot)
            completed()
            begin("rendering")
            available()
            rendered = self.renderer_factory(batch).render(decision, selected, (), context)
            rendered = m.RenderedAction.model_validate_json(rendered.model_dump_json())
            contents = selected.candidate.contents
            expected_packages = contents.packages if isinstance(contents, m.OfferAction) else ()
            if (
                rendered.snapshot != ref
                or rendered.supplier_id != snapshot.target_supplier_id
                or rendered.decision_ref != "sha256:" + semantic_hash(decision)
                or rendered.kind != contents.kind
                or rendered.payload.packages != expected_packages
            ):
                raise ContractViolation("invalid_schema: renderer edited the selected action")
            completed()
            begin("validation")
            available()
            validation = self.validator.validate_action(rendered, context, snapshot.state, snapshot.budget)
            validation = TypeAdapter(m.ValidationResult).validate_json(validation.model_dump_json())
            if validation.kind == "invalid":
